<?php require_once dirname(__DIR__).'/includes/auth.php';require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$quiz=['id'=>'','title'=>'','description'=>'','status'=>'draft','time_limit_minutes'=>'','show_score'=>1];$questions=[];if($id){$s=db()->prepare('SELECT * FROM quizzes WHERE id=?');$s->execute([$id]);$quiz=$s->fetch()?:exit('Quiz não encontrado.');$c=db()->prepare('SELECT COUNT(*) FROM attempts WHERE quiz_id=? AND submitted_at IS NOT NULL');$c->execute([$id]);if((int)$c->fetchColumn()>0){flash('error','Este quiz já recebeu respostas e foi bloqueado para preservar o histórico. Duplique-o criando um novo quiz.');redirect('admin/');}$s=db()->prepare('SELECT * FROM questions WHERE quiz_id=? ORDER BY position');$s->execute([$id]);$questions=$s->fetchAll();foreach($questions as &$q){$o=db()->prepare('SELECT * FROM question_options WHERE question_id=? ORDER BY position');$o->execute([$q['id']]);$q['options']=$o->fetchAll();}unset($q);}$pageTitle=($id?'Editar':'Criar').' quiz';require dirname(__DIR__).'/includes/header.php'; ?>
<section class="admin-head compact"><div><a class="back" href="<?= e(url('admin/')) ?>">← Voltar</a><h1><?= $id?'Editar quiz':'Criar novo quiz' ?></h1><p>Configure o desafio e as respostas corretas.</p></div></section>
<form class="editor" action="<?= e(url('admin/save_quiz.php')) ?>" method="post" id="quizEditor"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e((string)$quiz['id']) ?>">
<section class="form-card"><h2>Informações gerais</h2><div class="form-grid"><label class="wide">Título<input name="title" required maxlength="180" value="<?= e($quiz['title']) ?>" placeholder="Ex.: Desafio Cultura QMAX"></label><label class="wide">Descrição<textarea name="description" rows="3" placeholder="Uma breve apresentação do desafio"><?= e($quiz['description']) ?></textarea></label><label>Status<select name="status"><option value="draft" <?= $quiz['status']==='draft'?'selected':'' ?>>Rascunho</option><option value="published" <?= $quiz['status']==='published'?'selected':'' ?>>Publicado</option><option value="closed" <?= $quiz['status']==='closed'?'selected':'' ?>>Encerrado</option></select></label><label>Tempo limite (min)<input type="number" min="1" max="240" name="time_limit_minutes" value="<?= e((string)$quiz['time_limit_minutes']) ?>" placeholder="Opcional"></label><label class="check"><input type="checkbox" name="show_score" value="1" <?= $quiz['show_score']?'checked':'' ?>> Mostrar pontuação ao participante</label></div></section>
<div class="section-row"><div><h2>Perguntas</h2><p>Escolha a resposta correta para a correção automática.</p></div><button type="button" class="button secondary" id="addQuestion">＋ Adicionar pergunta</button></div><div id="questionsBuilder">
<?php foreach($questions as $i=>$q): ?><section class="question-builder"><div class="builder-head"><strong>Pergunta <span class="q-number"><?= $i+1 ?></span></strong><button type="button" class="remove-question">Remover</button></div><div class="form-grid"><label class="wide">Enunciado<textarea name="questions[<?= $i ?>][text]" required rows="2"><?= e($q['question_text']) ?></textarea></label><label>Tipo<select name="questions[<?= $i ?>][type]" class="question-type"><option value="single" <?= $q['type']==='single'?'selected':'' ?>>Múltipla escolha</option><option value="text" <?= $q['type']==='text'?'selected':'' ?>>Resposta aberta</option></select></label><label>Pontos<input type="number" min="0" max="100" name="questions[<?= $i ?>][points]" value="<?= (int)$q['points'] ?>"></label></div><div class="option-list"><?php foreach($q['options'] as $j=>$o): ?><div class="option-row"><input type="radio" name="questions[<?= $i ?>][correct]" value="<?= $j ?>" <?= $o['is_correct']?'checked':'' ?>><input name="questions[<?= $i ?>][options][]" value="<?= e($o['option_text']) ?>" placeholder="Alternativa" required><button type="button" class="remove-option">×</button></div><?php endforeach; ?></div><button type="button" class="add-option">＋ Alternativa</button></section><?php endforeach; ?></div>
<div class="savebar"><span>As alterações entram em vigor ao salvar.</span><button class="button" type="submit">Salvar quiz</button></div></form>
